import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import kotlin.math.min

fun isLucky(x: Long): Boolean {
    var n = x
    if (n <= 0) return false
    while (n > 0) {
        val d = n % 10
        if (d != 4L && d != 7L) return false
        n /= 10
    }
    return true
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toLong()
    var k = st.nextToken().toLong()

    // Precompute factorials up to 20 with cap > 1e18
    val fact = LongArray(21)
    fact[0] = 1L
    for (i in 1..20) {
        val v = fact[i - 1] * i
        fact[i] = if (v > 1_000_000_000_000_000_000L) 1_000_000_000_000_000_000L else v
    }

    // If n > 20, prefix is fixed, only last m = min(20, n) positions permuted
    val m = min(20L, n).toInt()
    val fixedPrefix = (n - m).toInt() // positions 1..fixedPrefix are fixed

    // Check if k-th permutation exists
    if (k > fact[m]) {
        println(-1)
        return
    }

    // Build the list of numbers in the permuted suffix
    val suffixStart = (n - m + 1).toInt()
    val available = ArrayList<Long>()
    for (i in suffixStart..n.toInt()) {
        available.add(i.toLong())
    }

    // Build the k-th permutation of the suffix (1-based k)
    val perm = LongArray(m)
    var kk = k - 1 // 0-based
    for (i in 0 until m) {
        val blockSize = fact[m - 1 - i]
        val idx = (kk / blockSize).toInt()
        kk %= blockSize
        perm[i] = available[idx]
        available.removeAt(idx)
    }

    var ans = 0L

    // Count lucky positions in fixed prefix: ai = i
    for (i in 1..fixedPrefix) {
        val pos = i.toLong()
        if (isLucky(pos) && isLucky(pos)) ans++
    }

    // Count lucky positions in permuted suffix
    for (i in 0 until m) {
        val pos = (fixedPrefix + 1 + i).toLong()
        val value = perm[i]
        if (isLucky(pos) && isLucky(value)) ans++
    }

    println(ans)
}

