fun genLucky(limit: Long): List<Int> {
    val res = ArrayList<Int>()
    fun dfs(cur: Long) {
        if (cur > limit) return
        if (cur != 0L) res.add(cur.toInt())
        dfs(cur * 10 + 4)
        dfs(cur * 10 + 7)
    }
    dfs(0)
    res.sort()
    return res
